import json, time, urllib.request, urllib.error
from datetime import datetime, timezone
B="http://localhost:8080"
tok=None
log=[]
def newtok():
    global tok
    r=urllib.request.Request(B+"/token",method="POST",data=b"")
    tok=json.load(urllib.request.urlopen(r))["token"]
def get(path):
    global tok
    for attempt in range(200):
        if tok is None: newtok()
        r=urllib.request.Request(B+path,headers={"Authorization":"Bearer "+tok})
        try:
            return json.load(urllib.request.urlopen(r))
        except urllib.error.HTTPError as e:
            body=e.read()[:200]
            log.append((path,e.code,dict(e.headers),body))
            if e.code==404: return None
            if e.code==401: newtok(); continue
            ra=e.headers.get("Retry-After")
            if ra is None:
                try: ra=json.loads(body).get("retry_after")
                except Exception: pass
            time.sleep(float(ra) if ra else 1)
        except Exception as ex:
            log.append((path,repr(ex))); time.sleep(1)
    raise SystemExit("gave up "+path)
orders=[]; seen={}; dups=0
p=1
while True:
    d=get(f"/orders?page={p}")
    for o in d["items"]:
        if o["id"] in seen:
            dups+=1
            if seen[o["id"]]!=o: print("DIFFERING DUP",o,seen[o["id"]])
        else:
            seen[o["id"]]=o
    if not d["next"] or p>=d["total_pages"] and not d["next"]: break
    p+=1
print("pages",p,"unique",len(seen),"dups",dups)
lo=datetime(2025,3,1,tzinfo=timezone.utc); hi=datetime(2025,6,1,tzinfo=timezone.utc)
def utc(s):
    return datetime.fromisoformat(s.replace("Z","+00:00")).astimezone(timezone.utc)
q=[o for o in seen.values() if o["status"]=="shipped" and lo<=utc(o["placed_at"])<hi]
cust={}
for o in q:
    c=o["customer_id"]
    if c not in cust: cust[c]=get(f"/customers/{c}")
reg={"north":0,"south":0,"east":0,"west":0}; miss=[]
for o in q:
    c=cust[o["customer_id"]]
    if c is None: miss.append(o); continue
    amt=(o["amount_cents"]*(100-c["discount_pct"])+50)//100
    reg[c["region"]]+=amt
print("missing customers",miss)
print("statuses",{s:sum(1 for o in seen.values() if o["status"]==s) for s in set(o["status"] for o in seen.values())})
res={"total_cents":sum(reg.values()),"order_count":len(q)-len(miss),"duplicates_skipped":dups,"by_region":reg}
print(res); print("errors:",len(log), [ (l[0],l[1]) for l in log[:15]]); print(log[:3])
json.dump(res,open("/workspace/result.json","w"),indent=2)
